const FRAME_BUDGET_MS = 16.67;
// One BeginMainFrame's worth of main-thread work overran badly:
const mainThreadCostMs = 58;

const overrunMs = +(mainThreadCostMs - FRAME_BUDGET_MS).toFixed(2);
// How many whole vsync ticks pass while this one frame is still being produced.
const staleFrames = Math.ceil(mainThreadCostMs / FRAME_BUDGET_MS) - 1;

console.log(`overrun=${overrunMs}ms stale=${staleFrames}`);
